  const intro=state.accessFlow==='premium'?'Masuk atau buat akun email sebelum mengklaim token Premium. Demo tamu tetap bisa digunakan tanpa akun.':'Akun bersifat opsional untuk demo. Masuk atau daftar agar kuota demo dapat disimpan pada server dan dipulihkan bersama akun.';
