function defaultCreatorCharacter(){return {name:'Mika',gender:'male',hairStyle:'spiky',hairColor:'#182743',eyeColor:'#58a9ef',accessory:'none',outfit:'uniform',bottom:'pants',clothingColor:'#345984',shoeColor:'#25314a',extra:'badge',expression:'happy',active:false};}
function normalizeCreatorCharacter(value){
  const base=defaultCreatorCharacter(),source=value&&typeof value==='object'?value:{};const result={...base,...source};
  for(const key of Object.keys(creatorOptions)){if(!creatorOptions[key].some(([option])=>option===result[key]))result[key]=base[key];}
  result.name=String(result.name||base.name).trim().slice(0,24)||base.name;result.active=Boolean(result.active);return result;
}
