function missionAvailability(mode,index){
  const access=globalModeAccess(mode);if(!access.unlocked)return {available:false,reason:access.reason};
  if(isDemoAccess()){
    if(mode!=='easy'||index<0||index>1)return {available:false,reason:'🔒 Misi Easy lanjutan, Medium, Hard, dan Mode Bule memerlukan Premium.'};
    const mission=missionBanks.easy[index];if(!mission||!DEMO_MISSION_IDS.has(mission.id))return {available:false,reason:'Misi ini tidak termasuk demo.'};
    const used=mission.questions.filter(question=>accessState.usedQuestionIds.has(question.id)).length;
    const active=profile.activeMission?.missionId===mission.id?profile.activeMission:null;
    if(index===1&&!missionBanks.easy[0].questions.every(question=>accessState.usedQuestionIds.has(question.id)))return {available:false,reason:'Jawab lima soal unik pada misi demo pertama untuk membuka misi kedua.'};
    if(used>=mission.questions.length){
      const activeAnswer=active?.answers?.[Math.max(0,Math.min(mission.questions.length-1,Number(active.index)||0))];
      if(activeAnswer&&String(activeAnswer.raw||'').trim())return {available:true,reason:'Lanjutkan jawaban tersimpan untuk menutup misi; tidak ada soal baru.'};
      return {available:false,reason:'Semua soal unik misi ini sudah digunakan. Soal demo tidak dapat diulang.'};
    }
    if(accessState.demoRemaining<=0){
      const activeAnswer=active?.answers?.[Math.max(0,Math.min(mission.questions.length-1,Number(active.index)||0))];
      if(activeAnswer&&String(activeAnswer.raw||'').trim())return {available:true,reason:'Lanjutkan jawaban tersimpan untuk menutup misi; tidak ada soal baru.'};
      return {available:false,reason:'🔒 Jatah 10 soal demo habis. Buka info Premium untuk langkah berikutnya.'};
    }
    return {available:true,reason:''};
  }
  const previous=missionBanks[mode]?.[index-1];if(previous&&!profile.missionStatus?.[previous.id]?.passed)return {available:false,reason:`Pass “${previous.title}” first to unlock this mission.`};
  return {available:true,reason:''};
}
