    cafe:`<ellipse cx="165" cy="121" rx="91" ry="30" fill="#fff"/><path d="M99 104 Q128 75 190 84 L225 104 Q196 137 124 129Z" fill="#dda257"/><path d="M119 99 Q158 87 204 104" stroke="#68aa63" stroke-width="9" stroke-linecap="round"/><path d="M270 68 H333 L325 142 Q299 153 277 141Z" fill="#d8f3fb" stroke="#6cafd1" stroke-width="4"/><path d="M280 101 H330" stroke="#8ec5dc" stroke-width="4"/><circle cx="365" cy="48" r="15" fill="#ffc94a"/>`,
