function renderStoryPlay(){
  if(!state.story)state.story={index:0,choice:null,correct:0,finished:false,showTranslation:false,rewarded:false};
  const story=state.story;
  if(story.finished)return `<div class="completion-page"><section class="completion-card story-completion"><div class="story-victory-avatars">${playerAvatar('cheer')}${animeAvatar('suki',story.correct>=4?'embarrassed':'smug')}</div><span class="level-tag">CERITA SELESAI</span><h1>Petualangan selesai!</h1><p>Kamu menjawab <b>${story.correct} dari ${storyScenes.length}</b> pilihan dengan tepat. ${story.correct>=4?'Kamu dan teman-teman menyelesaikan misi dengan percaya diri!':'Aki dan Rina mengajakmu berlatih lagi. Jawaban salah tidak menghapus progres.'}</p><div class="completion-rewards"><span>⭐ +25 XP</span><span>🪙 +4 koin</span></div><div class="hero-actions" style="justify-content:center"><button class="btn btn-primary" data-action="start-story">Mainkan lagi</button><button class="btn btn-secondary" data-action="nav" data-page="story">Kembali ke Story Mode</button></div></section></div>`;
  const scene=storyScenes[story.index],mood=story.choice===null?'thinking':story.choice===scene.answer?'cheer':'confused';
  return `<section class="story-experience"><header class="story-toolbar"><button class="btn btn-ghost btn-small" data-action="back">← Keluar</button><div><span class="level-tag">ADEGAN ${story.index+1} / ${storyScenes.length}</span><h1>${esc(scene.title.replace(/^Adegan \d+ · /,''))}</h1></div><button class="btn btn-ghost btn-small" data-action="story-translation">${story.showTranslation?'🙈 Sembunyikan arti':'👁️ Tampilkan arti'}</button></header><div class="story-progress-track"><span style="width:${(story.index+1)/storyScenes.length*100}%"></span></div><div class="story-stage"><div class="story-stage-art">${sceneSvg(scene.kind)}</div><div class="story-cast-rail"><div class="story-character-card ${scene.character==='suki'&&story.choice===scene.answer?'suki-shocked':''}">${animeAvatar(scene.character,mood)}<span><b>${esc(getCharacter(scene.character).name)}</b><small>${scene.character==='suki'?'Rival belajar':getCharacter(scene.character).role}</small></span></div><span class="story-cast-arrow">↔</span><div class="story-character-card story-player-card">${playerAvatar(mood)}<span><b>${esc(playerName())}</b><small>Karakter pemain</small></span></div></div></div><article class="story-dialog-panel"><div class="story-dialog-heading"><div><span class="roleplay-speaker">${esc(getCharacter(scene.character).name)} says</span><p>${esc(scene.en)}</p>${story.showTranslation?`<small class="story-translation">${esc(scene.id)}</small>`:''}</div><button class="icon-btn story-speak" data-action="speak" data-text="${esc(scene.en)}" data-voice-character="${esc(scene.character)}" aria-label="Putar dialog">🔊</button></div><div class="story-vocab">${scene.words.map(word=>`<button class="word-chip" data-action="speak" data-text="${esc(word)}">🔊 ${esc(word)}</button>`).join('')}</div><div class="story-question"><b>${esc(scene.question)}</b>${story.choice===null?`<div class="story-options">${scene.options.map(option=>`<button class="story-option" data-action="story-choice" data-choice="${esc(option)}">${esc(option)}</button>`).join('')}</div>`:`<div class="feedback ${story.choice===scene.answer?'good':'bad'}"><b>${story.choice===scene.answer?'Nice! Pilihanmu tepat.':'Belum tepat—tenang, kita belajar bareng.'}</b> ${esc(story.choice===scene.answer?scene.right:scene.wrong)}<div class="story-response-line"><span>${esc(scene.replyEn)}</span><button class="icon-btn" data-action="speak" data-text="${esc(scene.replyEn)}" data-voice-character="${esc(scene.character)}" aria-label="Putar balasan">🔊</button></div>${story.showTranslation?`<small class="story-translation">${esc(scene.replyId)}</small>`:''}</div><div class="story-dialog-actions"><button class="btn btn-ghost btn-small" data-action="back">Kembali</button><button class="btn btn-primary btn-small" data-action="story-next">${story.index===storyScenes.length-1?'Selesaikan cerita':'Lanjut →'}</button></div>`}</div></article><p class="story-audio-note">Dialog dan kosakata memakai Text-to-Speech perangkat bila tersedia. Audio tetap dapat diulang melalui tombol 🔊.</p></section>`;
}

