function renderSources(){
  return `<div class="page-heading"><div><span class="level-tag">SUMBER TAMBAHAN · WIKIPEDIA</span><h1>Belajar dari artikel</h1><p>Wikipedia membantu latihan membaca dan menambah wawasan—bukan pengganti kurikulum bahasa Inggris dari nol.</p></div></div><div class="inline-notice" style="margin-bottom:15px">🌐 Ringkasan offline dan terjemahan ditulis oleh English Quest—bukan kutipan artikel. Ringkasan online memakai cuplikan Wikipedia; atribusi dan riwayat kontributor tersedia pada halaman artikel, dengan lisensi CC BY-SA sesuai sumber.</div><div class="source-grid">${wikipediaSources.map(source=>`<article class="source-card"><div class="source-head"><span class="source-level">${esc(source.level)}</span><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer" class="source-link">Buka artikel ↗</a></div><h2>${esc(source.title)}</h2><div class="source-summary"><b>Simple English summary</b><p>${esc(source.summaryEn)}</p><b>Arti ringkas</b><p>${esc(source.summaryId)}</p></div><div class="story-vocab">${source.words.map(([en,id])=>`<span><b>${esc(en)}</b> = ${esc(id)}</span>`).join('')}</div><div class="source-actions"><button class="btn btn-secondary btn-small" data-action="fetch-source" data-source="${source.id}" ${state.sourceStatus==='loading'&&state.sourceId===source.id?'disabled':''}>${state.sourceStatus==='loading'&&state.sourceId===source.id?'Memuat…':'Ambil ringkasan Wikipedia online'}</button></div>${state.sourceId===source.id&&state.sourceStatus==='success'?`<div class="source-live"><b>Wikipedia summary (English)</b><p>${esc(state.sourceSummary)}</p><small>Teks ringkasan bersumber dari kontributor Wikipedia. Atribusi: <a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">artikel</a> · <a href="https://en.wikipedia.org/w/index.php?title=${encodeURIComponent(source.slug)}&amp;action=history" target="_blank" rel="noopener noreferrer">riwayat kontributor</a> · lisensi teks <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>.</small></div>`:''}${state.sourceId===source.id&&state.sourceStatus==='error'?`<div class="feedback bad">Tidak dapat memuat sekarang. Ringkasan offline di atas tetap tersedia; periksa koneksi lalu coba lagi.</div>`:''}<div class="source-attribution">Sumber: <a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">Wikipedia — ${esc(source.title)}</a>. Tidak ada teks atau gambar artikel yang disalin penuh.</div></article>`).join('')}</div><section class="panel" style="margin-top:17px"><h2 class="panel-title">Cara memakai sumber</h2><p class="panel-subtitle">Baca ringkasan English, tebak arti kata dari konteks, lalu cocokkan dengan arti Indonesia dan kosakata. Jika koneksi tidak tersedia, ringkasan dasar tetap tersimpan dalam aplikasi.</p></section>`;
}
async function fetchWikipediaSummary(sourceId){
  const source=wikipediaSources.find(item=>item.id===sourceId);if(!source)return;
  if(sourceController)sourceController.abort();
  const requestId=++sourceRequestId;const controller=typeof AbortController==='function'?new AbortController():null;sourceController=controller;
  state.sourceId=sourceId;state.sourceStatus='loading';state.sourceSummary='';state.sourceError='';render();
  const timer=setTimeout(()=>controller?.abort(),9000);
  try{
    const options={headers:{'accept':'application/json'}};if(controller)options.signal=controller.signal;
    const response=await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(source.slug)}`,options);
    if(!response.ok)throw new Error(`HTTP ${response.status}`);
    const data=await response.json();if(!data.extract)throw new Error('No summary');
    if(requestId!==sourceRequestId)return;
    state.sourceSummary=data.extract.slice(0,900);state.sourceStatus='success';
  }catch(error){if(requestId!==sourceRequestId)return;state.sourceStatus='error';state.sourceError=String(error);}
  finally{clearTimeout(timer);if(requestId===sourceRequestId){sourceController=null;if(state.page==='sources')render();}}
}

