function roleplayScenesForMode(mode=profile.settings.mode){if(mode==='easy')return roleplayScenes.slice(0,5);if(mode==='hard')return hardRoleplayScenes;return roleplayScenes;}
function startRoleplay(source='bule'){
  if(source==='bule'){const access=globalModeAccess('bule');if(!access.unlocked){showToast(access.reason);return;}state.missionMode='bule';profile.settings.mode='bule';saveProfile();state.page='mission-list';state.backPage='missions';render();return;}
  const scenes=roleplayScenesForMode(profile.settings.mode);
  state.roleplay={source,scenes,index:0,choice:null,correct:0,hintVisible:profile.settings.mode==='easy',finished:false,rewarded:false};
  state.page=source==='game'?'anime-dialogue':'bule';state.backPage=source==='game'?'games':'home';render();autoSpeakDialogue(scenes[0].en,scenes[0].speaker);
}
function evaluateRoleplay(answer){
  const game=state.roleplay;if(!game||game.choice!==null)return;
  const scenes=game.scenes||roleplayScenes;const scene=scenes[game.index];const normalized=normalize(answer);
  const exact=scene.accepted.some(item=>normalize(item)===normalized);const validStart=(scene.validStarts||[]).some(prefix=>normalized.startsWith(normalize(prefix)));const hasRequired=(scene.required||[]).every(word=>normalized.includes(normalize(word)));const natural=validStart&&hasRequired&&normalized.split(' ').length>=3;const correct=exact||natural;
  game.choice=correct?scene.answer:(answer||'__incorrect__');game.lastAnswer=answer;game.isCorrect=correct;
  if(correct){game.correct++;clearMistake(scene.words[0]);}else trackMistake(scene.words[0]);
  render();autoSpeakDialogue([{text:answer,character:'player'},{text:correct?scene.reply:scene.answer,character:scene.speaker}]);
}
function renderRoleplay(isGame=false){
  const game=state.roleplay,scenes=game?.scenes||roleplayScenes;
  if(!game)return `<div class="roleplay-intro"><div>${animeAvatar('aki','happy')}</div><div><span class="level-tag">${isGame?'ANIME DIALOGUE':'ENGLISH IMMERSION'}</span><h1>${isGame?'Anime Dialogue':'Mode Bule'}</h1><p>${isGame?'Practice everyday English with Aki, Rina, Naya, Bimo, and Suki.':'Choose a reply in simple English. Untuk membalas dengan mengetik, mainkan Story Chat Reply.'}</p><div class="hero-actions"><button class="btn btn-primary" data-action="start-roleplay" data-source="${isGame?'game':'bule'}">${isGame?'Start dialogue':'Start conversation practice'}</button><button class="btn btn-secondary" data-action="start-chat-reply" data-source="bule">💬 Story Chat Reply</button></div></div></div>`;
  if(game.finished)return `<div class="completion-page"><section class="completion-card"><div class="completion-emoji">🗣️</div><h1>${game.correct>=Math.ceil(scenes.length*.8)?'Awesome work!':'Nice try—keep practicing!'}</h1><p>You finished ${scenes.length} conversations and chose ${game.correct} strong replies. ${game.correct>=Math.ceil(scenes.length*.8)?'Your answers were clear and polite.':'Review the grammar tips, then try again. No penalty for mistakes.'}</p><div class="completion-rewards"><span>⭐ +15 XP</span><span>🪙 +3 coins</span></div><button class="btn btn-primary" data-action="start-roleplay" data-source="${game.source}">Play again</button> <button class="btn btn-secondary" data-action="nav" data-page="home">Home</button></section></div>`;
  const scene=scenes[game.index],speaker=getCharacter(scene.speaker),mood=game.choice===null?'thinking':game.isCorrect?'cheer':'confused';
  const hint=game.hintVisible?`<div class="roleplay-hint"><b>Petunjuk Indonesia:</b> ${esc(scene.id)}<br><small>${esc(scene.tip)}</small></div>`:'';
  return `<div class="roleplay-page"><div class="roleplay-top"><div><span class="level-tag">${isGame?'ANIME DIALOGUE':'MODE BULE'} · ${game.index+1}/${scenes.length}</span><h1>${esc(scene.place)}</h1><p>${isGame?'Pilih balasan yang paling sesuai.':'Choose a reply in simple English. Untuk mengetik sendiri, buka Story Chat Reply.'}</p></div><button class="btn btn-ghost btn-small" data-action="roleplay-hint">${game.hintVisible?'Hide hint':'Buka petunjuk Indonesia'}</button></div><div class="roleplay-scene"><div class="roleplay-scene-art">${sceneSvg(scene.kind)}</div><div class="roleplay-character">${animeAvatar(scene.speaker,mood)}<div><b>${esc(speaker.name)}</b><small>${esc(scene.place)}</small></div></div></div><section class="roleplay-dialogue"><div class="roleplay-message"><span class="roleplay-speaker">${esc(speaker.name)} says</span><div class="roleplay-speech-row"><h2>${esc(scene.en)}</h2><button class="icon-btn" data-action="speak" data-text="${esc(scene.en)}" data-voice-character="${esc(scene.speaker)}" aria-label="Putar dialog ${esc(speaker.name)}">🔊</button></div>${hint}</div><p class="roleplay-question">${esc(scene.question)}</p><div class="roleplay-options">${scene.options.map(option=>`<button class="story-option ${game.choice!==null?(option===scene.answer?'selected-correct':option===game.choice?'selected-wrong':''):''}" data-action="roleplay-choice" data-choice="${esc(option)}" ${game.choice!==null?'disabled':''}>${esc(option)}</button>`).join('')}</div>${game.choice!==null?`<div class="feedback ${game.isCorrect?'good':'bad'}"><b>${game.isCorrect?'Nice! Jawaban lu benar. Lanjut ke soal berikutnya!':'Belum tepat, bro. Coba perhatikan susunan katanya, ya!'}</b><br>${game.isCorrect?esc(scene.reply):`A more natural reply: <b>${esc(scene.answer)}</b><br>${esc(scene.tip)}`}${game.isCorrect?` <button class="btn btn-ghost btn-small" data-action="speak" data-text="${esc(scene.reply)}" data-voice-character="${esc(scene.speaker)}">🔊 Putar balasan</button>`:''}</div><button class="btn btn-primary" style="margin-top:14px" data-action="roleplay-next">${game.index===scenes.length-1?'Finish practice':'Next conversation →'}</button>`:''}</section><div class="roleplay-progress"><span>${animeAvatar(scene.speaker,'happy')}<span><b>${esc(speaker.name)} · cara belajar</b><small>${esc(scene.tip||speaker.teachingStyle)}</small></span></span><button class="btn btn-ghost btn-small" data-action="back">Exit</button></div></div>`;
}

