function chatReplyEpisodesForMode(mode=profile.settings.mode){if(mode==='easy')return chatReplyEpisodes.slice(0,5);if(mode==='medium')return chatReplyEpisodes.slice(0,8);return chatReplyEpisodes.slice();}
function startChatReply(source='story'){state.chatReply=null;state.page='chat-reply';state.backPage=source;render();window.scrollTo?.(0,0);}
function beginChatReply(){
  const episodes=chatReplyEpisodesForMode(profile.settings.mode),source=state.backPage;
  state.chatReply={episodes,source,index:0,log:[],input:'',checked:false,correct:false,score:0,wrongAttempts:0,hintVisible:false,finished:false,rewarded:false};
  state.page='chat-reply';state.backPage=source==='story'||source==='bule'?source:'games';
  state.chatReply.log.push(...episodes[0].messages);render();window.scrollTo?.(0,0);autoSpeakDialogue(episodes[0].messages.map(message=>({text:message.text,character:message.speaker})));
}
function chatReplyContains(text,term){return (` ${text} `).includes(` ${normalize(term)} `);}
function chatReplyMatches(scene,value){
  const text=normalize(value),tokens=text.split(' ').filter(Boolean);
  if(!text)return false;
  if((scene.accepted||[]).some(answer=>normalize(answer)===text))return true;
  if(tokens.length<(scene.minWords||3))return false;
  if((scene.forbidden||[]).some(fragment=>text.includes(normalize(fragment))))return false;
  return (scene.requiredGroups||[]).every(group=>group.some(term=>chatReplyContains(text,term)));
}
function submitChatReply(){
  const game=state.chatReply;if(!game||game.finished||game.correct)return;
  const scene=game.episodes[game.index],reply=String(game.input||'').trim();
  if(!reply){showToast('Ketik satu balasan singkat dalam bahasa Inggris dulu.');return;}
  game.checked=true;game.correct=chatReplyMatches(scene,reply);
  if(game.correct){game.score++;if(scene.word)clearMistake(scene.word);game.log.push({speaker:'player',text:reply,player:true},{speaker:scene.npc,text:scene.successReply});render();playUiSound('success');autoSpeakDialogue([{text:reply,character:'player'},{text:scene.successReply,character:scene.npc}]);}
  else{game.wrongAttempts++;if(scene.word)trackMistake(scene.word);game.hintVisible=true;render();playUiSound('miss');autoSpeakDialogue(scene.nudge,scene.npc);}
}
function advanceChatReply(){
  const game=state.chatReply;if(!game||!game.correct)return;
  if(game.index===game.episodes.length-1){game.finished=true;if(!game.rewarded){game.rewarded=true;game.rewardXp=20;game.rewardCoins=3;addReward(20,3,'game');recordGameResult('storyChatReply',game.score,game.episodes.length);}render();autoSpeakDialogue('You finished the English Fair chat story. Great work!');return;}
  game.index++;game.input='';game.checked=false;game.correct=false;game.hintVisible=false;
  const scene=game.episodes[game.index];game.log.push(...scene.messages);game.log=game.log.slice(-9);render();autoSpeakDialogue(scene.messages.map(message=>({text:message.text,character:message.speaker})));
}
function renderChatReply(){
  const game=state.chatReply;
  if(!game)return `<div class="page-heading"><div><span class="level-tag">STORY MODE · TYPING & ENGLISH</span><h1>Story Chat Reply</h1><p>Jalani grup chat English Fair bersama lima karakter. Ketik balasanmu sendiri, pelajari pola kalimat, lalu lihat cerita bergerak.</p></div><button class="btn btn-ghost btn-small" data-action="back">← Kembali</button></div><section class="chat-story-intro panel"><div class="chat-story-cast">${['aki','rina','naya','bimo','suki'].map(id=>`<div>${animeAvatar(id,'happy')}<b>${esc(getCharacter(id).name)}</b><small>${esc(getCharacter(id).teachingStyle)}</small></div>`).join('')}</div><div class="chat-story-brief"><span class="level-tag">${chatReplyEpisodesForMode(profile.settings.mode).length} ADEGAN · MODE ${esc(modeMeta[profile.settings.mode].name.toUpperCase())}</span><h2>Siapkan English Fair bersama teman-teman</h2><p>Aki memecah tugas menjadi langkah kecil, Rina mencari pola praktis, Naya memakai gambaran visual, Bimo memberi waktu untuk berpikir, dan Suki menantangmu dengan gaya rivalnya.</p><div class="inline-notice">Ketik kalimatmu sendiri dalam bahasa Inggris. Salah tidak mengurangi progres; kamu akan mendapat petunjuk, contoh balasan, dan kesempatan mencoba lagi.</div><div class="hero-actions"><button class="btn btn-primary" data-action="chat-reply-start">💬 Mulai chat story</button><button class="btn btn-secondary" data-action="back">Kembali</button></div></div></section>`;
  if(game.finished)return `<section class="completion-page"><article class="completion-card chat-story-completion"><div class="chat-story-cast compact">${['aki','rina','naya','bimo','suki'].map(id=>animeAvatar(id,id==='suki'?'embarrassed':'cheer')).join('')}</div><span class="level-tag">CHAT STORY SELESAI</span><h1>English Fair berhasil!</h1><p>Kamu mengetik ${game.episodes.length} balasan dan membantu semua karakter. Suki masih pura-pura tidak terkesan, tapi progresmu nyata.</p><div class="completion-rewards"><span>⭐ +${game.rewardXp||20} XP</span><span>🪙 +${game.rewardCoins||3}</span></div><div class="hero-actions" style="justify-content:center"><button class="btn btn-primary" data-action="chat-reply-restart">Main lagi</button><button class="btn btn-secondary" data-action="${game.source==='story'?'nav':'back'}" ${game.source==='story'?'data-page="story"':''}>${game.source==='story'?'Kembali ke Story Mode':'Kembali'}</button></div></article></section>`;
  const scene=game.episodes[game.index],character=getCharacter(scene.npc),visibleLog=game.log.slice(-9);
  const messages=visibleLog.map(message=>{const player=message.player||message.speaker==='player',speaker=player?playerName():getCharacter(message.speaker).name;return `<div class="chat-line ${player?'from-player':''}">${player?playerAvatar('happy','chat-line-avatar'):animeAvatar(message.speaker,message.speaker===scene.npc&&game.correct?'cheer':'happy','chat-line-avatar')}<div class="chat-bubble"><b>${esc(speaker)}</b><p>${esc(message.text)}</p></div></div>`;}).join('');
  const feedback=!game.checked?'':game.correct?`<div class="chat-feedback good" role="status"><b>${esc(character.name)} replied</b><p>${esc(scene.successReply)}</p><small>${esc(scene.successId)}</small></div>`:`<div class="chat-feedback retry" id="chat-reply-feedback" role="status"><b>${esc(character.name)}:</b> ${esc(scene.nudge)}<p><b>Contoh balasan:</b> ${esc(scene.sample)}</p><small>${esc(scene.sampleId)}</small></div>`;
  return `<div class="chat-story-page"><header class="chat-story-header"><button class="btn btn-ghost btn-small" data-action="back">← Keluar</button><div><span class="level-tag">STORY CHAT · ${game.index+1}/${game.episodes.length}</span><h1>${esc(scene.place)}</h1><p>Balasan benar: ${game.score}/${game.episodes.length}</p></div><span class="stat-pill">✍️ ${game.index+1}/${game.episodes.length}</span></header><div class="chat-progress"><span style="width:${Math.round(game.index/game.episodes.length*100)}%"></span></div><section class="chat-story-card"><div class="chat-group-head"><span class="chat-group-icon">💬</span><div><b>English Fair · Group Chat</b><small>${esc(modeMeta[profile.settings.mode].name)} · dialog tersimpan di sesi ini</small></div><span class="chat-online-dot" aria-label="Cerita aktif"></span></div><div class="chat-log" aria-live="polite">${messages}</div><div class="chat-challenge"><div class="chat-challenge-character">${animeAvatar(scene.npc,game.checked?(game.correct?'cheer':scene.npc==='suki'?'smug':'thinking'):'thinking')}<span><b>${esc(character.name)}</b><small>${esc(character.role)}</small></span></div><h2>${esc(scene.objective)}</h2><p class="chat-method"><b>Gaya belajar:</b> ${esc(character.teachingStyle)}</p><button class="btn btn-ghost btn-small" data-action="chat-reply-hint">${game.hintVisible?'Sembunyikan petunjuk':'💡 Petunjuk bahasa'}</button>${game.hintVisible?`<div class="chat-hint">${esc(scene.hint)}<br><small>${esc(character.tagline)}</small></div>`:''}${feedback}<label class="chat-compose-label" for="chat-reply-input">Tulis balasan dalam bahasa Inggris</label><textarea id="chat-reply-input" class="chat-reply-input" maxlength="180" rows="2" placeholder="Type your reply…" ${game.correct?'disabled':''}>${esc(game.input)}</textarea><div class="chat-compose-footer"><small><span id="chat-reply-count">${game.input.length}</span>/180 karakter · kalimatmu tidak dikirim ke mana pun</small><button class="btn ${game.correct?'btn-primary':'btn-secondary'}" data-action="${game.correct?'chat-reply-next':'chat-reply-submit'}">${game.correct?game.index===game.episodes.length-1?'Selesaikan cerita':'Adegan berikutnya →':'Cek balasan'}</button></div></div></section></div>`;
}

