function startNpcQuest(){
  const scenes=shuffle(npcQuestEpisodes).map(person=>({...shuffle(person.variants)[0],npc:person.id}));
  state.npcQuest={scenes,index:0,choice:null,correct:0,attempts:0,isCorrect:false,showHint:false,finished:false,rewarded:false};
  state.page='npc-quest';state.backPage='games';render();autoSpeakDialogue(scenes[0].en,scenes[0].npc);
}
function answerNpcQuest(choice){
  const game=state.npcQuest;if(!game||game.finished||game.choice!==null)return;
  const scene=game.scenes[game.index];game.choice=choice;game.isCorrect=normalize(choice)===normalize(scene.answer);
  if(game.isCorrect){game.correct++;clearMistake(scene.word);}else{game.attempts++;trackMistake(scene.word);game.showHint=true;}
  render();playUiSound(game.isCorrect?'success':'miss');autoSpeakDialogue([{text:choice,character:'player'},{text:game.isCorrect?scene.reply:scene.wrongReply,character:scene.npc}]);
}
function retryNpcQuest(){
  const game=state.npcQuest;if(!game||game.finished||game.choice===null||game.isCorrect)return;
  const scene=game.scenes[game.index];game.choice=null;game.isCorrect=false;render();autoSpeakDialogue(scene.retryLine,scene.npc);
}
function advanceNpcQuest(){
  const game=state.npcQuest;if(!game||game.finished||game.choice===null||!game.isCorrect)return;
  if(game.index===game.scenes.length-1){game.finished=true;if(!game.rewarded){game.rewarded=true;addReward(15,3,'game');recordGameResult('npcQuest',game.correct,game.scenes.length);}render();autoSpeakDialogue('Great teamwork! You completed all the NPC missions.');return;}
  game.index++;game.choice=null;game.isCorrect=false;game.showHint=false;render();autoSpeakDialogue(game.scenes[game.index].en,game.scenes[game.index].npc);
}
function renderNpcQuest(){
  const game=state.npcQuest;
  if(!game)return `<div class="game-board npc-quest-intro"><div class="page-heading"><div><span class="level-tag">MINI-GAME · NPC QUEST</span><h1>Misi bersama teman-teman</h1><p>Temui Aki, Rina, Naya, Bimo, dan Suki. Cara mengajar, kepribadian, serta respons mereka berbeda.</p></div></div><div class="npc-quest-cast">${npcQuestEpisodes.map(({id})=>`<div class="npc-quest-cast-card">${animeAvatar(id,'wave')}<b>${esc(getCharacter(id).name)}</b><small>${esc(getCharacter(id).role)}</small></div>`).join('')}</div><section class="panel npc-quest-brief"><div class="mission-top"><div><span class="level-tag">${npcQuestEpisodes.length} MISI · DIALOG BERCABANG</span><h2 class="panel-title">Bantu teman di sekolah, kafe, klub, dan perjalanan</h2><p class="panel-subtitle">Jawaban salah tidak mengurangi skor atau progres. Baca petunjuk dan coba lagi sampai berhasil.</p></div><div class="mission-emoji">🧭</div></div><ul><li>Dialog NPC dibacakan otomatis bila TTS tersedia.</li><li>Pilih jawaban, dengarkan respons karakter, dan lihat ekspresinya berubah.</li><li>Sentuh tombol 🔊 untuk mengulang dialog kapan saja.</li></ul><div class="hero-actions"><button class="btn btn-primary" data-action="start-npc-quest">Mulai ${npcQuestEpisodes.length} misi →</button><button class="btn btn-secondary" data-action="back">Kembali ke game</button></div></section></div>`;
  if(game.finished){
    const names=[...new Set(game.scenes.map(scene=>getCharacter(scene.npc).name))].join(', ');
    return `<div class="completion-page"><section class="completion-card npc-quest-completion"><div class="npc-quest-cast">${game.scenes.map(scene=>animeAvatar(scene.npc,scene.npc==='suki'?'embarrassed':'cheer')).join('')}</div><span class="level-tag">SEMUA MISI SELESAI</span><h1>Kerja tim yang hebat!</h1><p>Kamu membantu ${esc(names)} menyelesaikan <b>${game.scenes.length} misi</b>. Setiap karakter mendapat respons dan cara mengajar yang berbeda.</p><div class="completion-rewards"><span>⭐ +15 XP</span><span>🪙 +3 koin</span></div><div class="hero-actions" style="justify-content:center"><button class="btn btn-primary" data-action="start-npc-quest">Mainkan misi baru</button><button class="btn btn-secondary" data-action="back">Kembali ke mini-game</button></div></section></div>`;
  }
  const scene=game.scenes[game.index],character=getCharacter(scene.npc),mood=game.choice===null?'wave':game.isCorrect?(scene.npc==='suki'?'shocked':'cheer'):(scene.npc==='suki'?'smug':'confused');
  const options=scene.options.map(option=>{const cls=game.choice!==null?(option===game.choice?(game.isCorrect?'correct':'incorrect'):''):'';return `<button class="choice-btn ${cls}" data-action="npc-answer" data-choice="${esc(option)}" ${game.choice!==null?'disabled':''}>${esc(option)}</button>`;}).join('');
  const response=game.choice===null?'':`<div class="npc-quest-response ${game.isCorrect?'good':'retry'}" role="status"><div><b>${game.isCorrect?esc(character.name):'Petunjuk dari '+esc(character.name)}</b><p>${esc(game.isCorrect?scene.reply:scene.wrongReply)}</p>${game.isCorrect?`<small>${esc(scene.replyId)}</small>`:`<small><b>Petunjuk:</b> ${esc(scene.tip)}</small>`}</div><button class="icon-btn" data-action="speak" data-text="${esc(game.isCorrect?scene.reply:scene.wrongReply)}" data-voice-character="${esc(scene.npc)}" aria-label="Ulangi balasan">🔊</button></div>`;
  const persistentHint=game.showHint&&game.choice===null?`<div class="npc-quest-followup-tip" role="note"><b>Petunjuk tetap tersedia:</b> ${esc(scene.tip)}</div>`:'';
  return `<div class="game-board npc-quest-page"><header class="npc-quest-header"><button class="btn btn-ghost btn-small" data-action="back">← Keluar</button><div><span class="level-tag">NPC QUEST · MISI ${game.index+1}/${game.scenes.length}</span><h1>${esc(scene.place)}</h1><p>Misi selesai: ${game.correct}/${game.scenes.length} · jawaban salah boleh diulang.</p></div><span class="stat-pill">🧭 ${game.index+1}/${game.scenes.length}</span></header><div class="npc-quest-progress"><span style="width:${Math.round(game.index/game.scenes.length*100)}%"></span></div><section class="npc-quest-card"><div class="npc-quest-character ${game.choice===null?'':'mood-'+mood}">${animeAvatar(scene.npc,mood,'npc-quest-avatar')}<div><span class="roleplay-speaker">${esc(character.role)}</span><h2>${esc(character.name)}</h2><small>${scene.npc==='suki'?'“Hmph. Buktikan kalau kamu bisa!”':`“${esc(character.tagline)}”`}</small></div></div><div class="npc-quest-dialogue"><span class="level-tag">${esc(character.name)} BERBICARA</span><div class="npc-quest-speech-row"><p>${esc(scene.en)}</p><button class="icon-btn" data-action="speak" data-text="${esc(scene.en)}" data-voice-character="${esc(scene.npc)}" aria-label="Dengarkan dialog ${esc(character.name)}">🔊</button></div><small>${esc(scene.id)}</small></div><div class="npc-quest-objective"><span>🎯 TUJUAN MISI</span><b>${esc(scene.objective)}</b></div>${persistentHint}<div class="npc-quest-question"><b>${esc(scene.prompt)}</b><div class="choice-grid">${options}</div></div>${response}<div class="hero-actions npc-quest-actions">${game.choice===null?'':game.isCorrect?`<button class="btn btn-primary" data-action="npc-next">${game.index===game.scenes.length-1?'Selesaikan misi':'Misi berikutnya →'}</button>`:`<button class="btn btn-secondary" data-action="npc-retry">Coba lagi tanpa penalti</button>`}</div></section></div>`;
}

