function startWordHunter(){
  const pool=vocabularyForMode(profile.settings.mode).filter(item=>item.en&&item.id);const unique=[];const seen=new Set();for(const item of shuffle(pool)){const key=normalize(item.en);if(!seen.has(key)){seen.add(key);unique.push(item);}}
  const count=Math.min(5,unique.length);const roundItems=unique.slice(0,count);const difficulty=profile.settings.mode==='easy'?3:profile.settings.mode==='hard'?7:5;
  const rounds=roundItems.map(target=>{const distractors=shuffle(unique.filter(item=>normalize(item.en)!==normalize(target.en))).slice(0,difficulty);return {target,options:shuffle([target,...distractors]).map(item=>item.en)};});
  state.hunt={rounds,index:0,answer:null,correct:false,score:0,finished:false,rewarded:false};state.page='word-hunter';state.backPage='games';render();
}
function renderWordHunter(){
  const game=state.hunt;
  if(!game)return `<div class="game-board"><div class="page-heading"><div><h1>Word Hunter</h1><p>Temukan kata Inggris dari artinya. Pilih jawaban yang cocok dengan arti dan konteks.</p></div></div>${animeCoach('aki','thinking','Start your hunt! In Easy, you have fewer choices and every hint stays visible.')}<button class="btn btn-primary" data-action="start-game" data-game="hunter">Mulai berburu kata</button> <button class="btn btn-secondary" data-action="back">Kembali</button></div>`;
  if(game.finished)return `<div class="completion-page"><section class="completion-card"><div class="completion-emoji">🔎</div><h1>Perburuan selesai!</h1><p>Kamu menemukan <b>${game.score} dari ${game.rounds.length}</b> kata. Kata yang keliru masuk ke daftar review—tanpa kehilangan progres.</p><div class="completion-rewards"><span>⭐ +${game.rewardXp||15} XP</span><span>🪙 +${game.rewardCoins||3} koin</span></div><button class="btn btn-primary" data-action="start-game" data-game="hunter">Main lagi</button> <button class="btn btn-secondary" data-action="back">Kembali ke permainan</button></section></div>`;
  const round=game.rounds[game.index],answered=game.answer!==null,translation=profile.settings.mode==='bule'?`Find the English word for: “${round.target.id}”`:`Temukan kata Inggris untuk arti: “${round.target.id}”`;
  const hint=profile.settings.mode==='easy'?`Petunjuk: ${round.target.pron||'Perhatikan arti kata.'}`:profile.settings.mode==='hard'?`Tantangan: pilih berdasarkan arti dan ingat konteks penggunaannya.`:`Perhatikan arti dan panduan baca, lalu pilih kata yang paling sesuai.`;
  return `<div class="game-board"><div class="page-heading"><div><span class="level-tag">WORD HUNTER · ${game.index+1}/${game.rounds.length} · ${esc(modeMeta[profile.settings.mode].name.toUpperCase())}</span><h1 style="margin-top:6px">Cari kata yang tepat</h1><p>${esc(translation)}</p></div><button class="btn btn-ghost btn-small" data-action="back">Keluar</button></div>${animeCoach('aki',answered?(game.correct?'cheer':'confused'):'thinking',answered?(game.correct?'Nice! Jawaban lu benar. Lanjut ke soal berikutnya!':'Belum tepat, bro. Coba perhatikan arti katanya, ya.'):'Lihat arti dan petunjuknya, lalu buru kata yang cocok.')}<div class="game-intro"><span class="game-intro-icon">🧭</span><p><b>Skor: ${game.score}/${game.index+(answered?1:0)}</b><br>${esc(hint)}</p></div><div class="hunt-grid">${round.options.map(word=>`<button class="hunt-option ${answered?(normalize(word)===normalize(round.target.en)?'correct':normalize(word)===normalize(game.answer)?'incorrect':''):''}" data-action="hunt-answer" data-choice="${esc(word)}" ${answered?'disabled':''}>${esc(word)}</button>`).join('')}</div>${answered?`<div class="feedback ${game.correct?'good':'bad'}"><b>${game.correct?'Nice! Jawaban lu benar. Lanjut ke soal berikutnya!':'Belum tepat, bro. Coba perhatikan susunan katanya, ya!'}</b><br><b>${esc(round.target.en)}</b> berarti “${esc(round.target.id)}”. ${esc(game.correct?'Kata ini cocok dengan arti yang diminta.':'Jawaban yang benar sudah ditandai. Baca arti dan pelafalan, lalu coba lagi di kesempatan berikutnya.') }<div class="example-pron">Cara baca: ${esc(round.target.pron||'—')}</div></div><button class="btn btn-primary" style="margin-top:13px" data-action="hunt-next">${game.index===game.rounds.length-1?'Lihat hasil':'Berikutnya →'}</button>`:''}</div>`;
}

function renderWordMatch(){
  if(!state.match)return `<div class="game-board"><div class="page-heading"><div><h1>Vocabulary Match</h1><p>Pasangkan kata di kiri dengan arti yang tepat di kanan.</p></div></div><button class="btn btn-primary" data-action="start-game" data-game="wordmatch">Mulai permainan</button></div>`;
  const game=state.match,done=game.matched.length===game.pairs.length;
  return `<div class="game-board"><div class="page-heading"><div><span class="level-tag">VOCABULARY MATCH · ${game.matched.length}/${game.pairs.length} PASANG</span><h1 style="margin-top:6px">Cocokkan kata</h1><p>Pilih satu kata Inggris, lalu pilih arti Indonesianya.</p></div><button class="btn btn-ghost btn-small" data-action="start-game" data-game="wordmatch">Ulangi</button></div><div class="game-intro"><span class="game-intro-icon">🔗</span><p><b>Skor: ${game.score}</b><br>${done?'Semua pasangan benar!':'Tidak ada pengurangan poin jika salah. Coba lagi dengan santai.'}</p></div><div class="match-board"><div class="match-column">${game.pairs.map((pair,index)=>`<button class="match-card ${game.matched.includes(index)?'matched':game.selectedEn===index?'selected':''} ${game.wrong&&game.wrong.includes(index)?'wrong':''}" data-action="match-select" data-side="en" data-index="${index}" ${game.matched.includes(index)?'disabled':''}>${esc(pair.en)}</button>`).join('')}</div><div class="match-column">${game.idOrder.map(index=>`<button class="match-card ${game.matched.includes(index)?'matched':game.selectedId===index?'selected':''} ${game.wrong&&game.wrong.includes(index)?'wrong':''}" data-action="match-select" data-side="id" data-index="${index}" ${game.matched.includes(index)?'disabled':''}>${esc(game.pairs[index].id)}</button>`).join('')}</div></div>${game.lastFeedback?`<div class="feedback ${game.lastFeedbackGood?'good':'bad'}">${esc(game.lastFeedback)}</div>`:''}${done?`<div class="quiz-result"><div class="big-emoji">🏆</div><h2>Pasangan lengkap!</h2><p>Kamu mencocokkan ${game.pairs.length} kata dengan benar. +15 XP dan +4 koin!</p><button class="btn btn-primary" data-action="start-game" data-game="wordmatch">Main lagi</button></div>`:''}<div style="margin-top:17px"><button class="btn btn-secondary" data-action="back">← Kembali ke permainan</button></div></div>`;
}
