function renderListening(){
  const soundReady=audioAvailable()&&profile.settings.sound;
  if(!state.listen)return `<div class="page-heading"><div><span class="level-tag">LISTENING DETECTIVE</span><h1>Listening Detective</h1><p>Dengarkan dialog bahasa Inggris dengan TTS perangkat, lalu pilih artinya. Teks dan terjemahan disembunyikan sampai kamu menjawab.</p></div></div><div class="two-col"><section class="panel"><div style="width:100%;max-width:370px;margin:0 auto 12px">${sceneSvg('listening')}</div><h2 class="panel-title">Cara bermain</h2><p class="panel-subtitle">Setiap sesi berisi lima cuplikan audio. Jawaban salah tidak mengurangi poin; setelah menjawab, teks Inggris, arti, dan pelafalan akan muncul.</p><div class="inline-notice" style="margin-top:13px">${soundReady?'🔊 TTS bahasa Inggris siap bila voice perangkat tersedia.':'ℹ️ Jika voice belum tersedia, aktifkan paket suara English di perangkat. Kalimat dan arti tetap tersembunyi sampai kamu menjawab.'}</div><button class="btn btn-primary btn-block" style="margin-top:15px" data-action="start-listening">🎧 Mulai listening</button></section><section class="panel"><h2 class="panel-title">Kontrol audio</h2><p class="panel-subtitle">Voice: <b>${esc(voiceModeStatus())}</b><br>Kecepatan saat ini: <b>${Math.round((profile.settings.speechRate||1)*100)}%</b></p><div class="audio-rate-control"><button class="btn btn-secondary btn-small" data-action="audio-speed-down" aria-label="Perlambat audio">−</button><span>${Math.round((profile.settings.speechRate||1)*100)}%</span><button class="btn btn-secondary btn-small" data-action="audio-speed-up" aria-label="Percepat audio">+</button></div><p class="panel-subtitle" style="margin-top:14px">Jika TTS gagal, pesan kesalahan ditampilkan dan kamu tetap dapat memilih petunjuk teks secara sengaja.</p></section></div>`;
  const game=state.listen;
  if(game.finished)return `<div class="completion-page"><section class="completion-card"><div class="completion-emoji">🎧</div><h1>Telingamu makin terlatih!</h1><p>Skor listening: <b>${game.score}/${game.items.length}</b>. Setiap soal menampilkan teks dan arti setelah kamu menjawab.</p><div class="completion-rewards"><span>⭐ +15 XP</span><span>🪙 +3 koin</span></div><button class="btn btn-primary" data-action="start-listening">Latihan lagi</button> <button class="btn btn-secondary" data-action="nav" data-page="home">Beranda</button></section></div>`;
  const item=game.items[game.index];
  return `<div class="game-board listen-session"><div class="page-heading"><div><span class="level-tag">LISTENING ${game.index+1}/${game.items.length}</span><h1 style="margin-top:6px">Dengar baik-baik</h1><p>Pilih arti bahasa Indonesia dari kalimat yang kamu dengar.</p></div><button class="btn btn-ghost btn-small" data-action="back">Keluar</button></div><div class="listen-card"><button class="listen-play" data-action="listen-play" aria-label="Putar audio" ${soundReady?'':'disabled'}>▶</button><p>Tekan untuk memutar kalimat bahasa Inggris</p><div class="audio-rate-control"><button class="btn btn-secondary btn-small" data-action="audio-speed-down">−</button><span>Kecepatan ${Math.round((profile.settings.speechRate||1)*100)}%</span><button class="btn btn-secondary btn-small" data-action="audio-speed-up">+</button></div><div class="hero-actions" style="justify-content:center;margin-top:10px"><button class="btn btn-secondary btn-small" data-action="listen-play-slow" ${soundReady?'':'disabled'}>🐢 Putar pelan</button><button class="btn btn-ghost btn-small" data-action="listen-play" ${soundReady?'':'disabled'}>🔁 Ulangi</button></div>${!soundReady?`<div class="inline-notice" style="margin-top:12px"><b>Audio belum siap.</b> Teks tetap disembunyikan agar arti tidak langsung terbocorkan.</div>`:''}${audioState.status==='error'?`<div class="feedback bad" role="alert">TTS gagal: ${esc(audioState.error||'voice tidak tersedia')}. Coba putar ulang atau periksa paket suara English di perangkat. Kalimat dan arti akan muncul setelah kamu menjawab.</div>`:''}</div><div class="choice-grid">${item.options.map(option=>`<button class="choice-btn ${game.answer?(option===item.id?'correct':option===game.answer?'incorrect':''):''}" data-action="listen-answer" data-choice="${esc(option)}" ${game.answer?'disabled':''}>${esc(option)}</button>`).join('')}</div>${game.answer?`<div class="feedback ${game.answer===item.id?'good':'bad'}">${game.answer===item.id?'Nice! Jawabanmu benar.':'Belum tepat—tidak ada pengurangan nilai.'}<div class="listen-reveal-answer"><b>Kalimat:</b> “${esc(item.en)}”<br><b>Terjemahan:</b> ${esc(item.id)}<br><b>Cara baca:</b> ${esc(item.pron||'—')}</div><div class="lesson-tools"><button class="btn btn-ghost btn-small" data-action="speak" data-text="${esc(item.en)}">🔁 Dengarkan lagi</button><button class="btn btn-primary btn-small" data-action="listen-next">${game.index===game.items.length-1?'Lihat hasil':'Berikutnya →'}</button></div></div>`:''}<div style="margin-top:14px"><button class="btn btn-ghost" data-action="nav" data-page="home">← Kembali ke beranda</button></div></div>`;
}
function renderRush(){
  const game=state.rush;
  if(!game){const noTimer=profile.settings.mode==='easy';return `<div class="page-heading"><div><span class="level-tag">SPEED QUIZ · ${modeMeta[profile.settings.mode].name.toUpperCase()}</span><h1>Speed Quiz</h1><p>Atur durasi sesuai kenyamananmu. Jawaban salah tidak mengurangi poin.</p></div></div>${animeCoach('aki','cheer',noTimer?'Easy mode: no timer. Take your time!':'Ready, bro? Pilih timer yang cocok dan gas!')}<div class="game-grid"><article class="game-card green"><span class="game-card-icon">🌱</span><h3>Tanpa timer</h3><p>Mode Easy selalu tanpa batas waktu.</p><button class="btn btn-primary btn-small" data-action="start-rush" data-mode="free">Mulai santai</button></article>${noTimer?'':[15,30,60].map(duration=>`<article class="game-card ${duration===60?'blue':'yellow'}"><span class="game-card-icon">⏱️</span><h3>${duration} detik</h3><p>${duration===15?'Tantangan cepat.':duration===30?'Tempo sedang.':'Durasi lebih santai.'}</p><button class="btn btn-secondary btn-small" data-action="start-rush" data-mode="timed" data-duration="${duration}">Mulai ${duration} dtk</button></article>`).join('')}</div><div class="inline-notice" style="margin-top:14px">Mode aktif: <b>${esc(modeMeta[profile.settings.mode].name)}</b>. Kosakata menyesuaikan mode; materi kursus tetap mengikuti jalur level.</div>`;}
  if(game.finished)return `<div class="completion-page"><section class="completion-card"><div class="completion-emoji">⚡</div><h1>Sesi selesai, nice!</h1><p>Kamu menjawab <b>${game.score}</b> dengan benar dari ${game.answered} soal. ${game.mode==='free'?'Terus latihan sedikit demi sedikit.':'Latihan berikutnya, coba lampaui skormu!'}</p><div class="completion-rewards"><span>⭐ +${game.rewardXp||5} XP</span><span>🪙 +${game.rewardCoins||2} koin</span></div><button class="btn btn-primary" data-action="start-rush" data-mode="${game.mode}" data-duration="${game.duration}">Main lagi</button> <button class="btn btn-secondary" data-action="nav" data-page="games">Semua permainan</button></section></div>`;
  const item=game.current;
  return `<div class="game-board"><div class="page-heading"><div><span class="level-tag">SPEED QUIZ · ${esc(modeMeta[profile.settings.mode].name.toUpperCase())}</span><h1 style="margin-top:6px">Apa arti kata ini?</h1><p>Jawaban salah tidak mengurangi poin. Fokus dan nikmati latihan.</p></div><button class="btn btn-ghost btn-small" data-action="finish-rush">Selesai</button></div><div class="stats-grid" style="margin:0 0 14px"><div class="stat-card"><div class="stat-card-icon">✅</div><div><b>${game.score}</b><span>Benar</span></div></div><div class="stat-card"><div class="stat-card-icon">📝</div><div><b>${game.answered}</b><span>Dijawab</span></div></div><div class="stat-card"><div class="stat-card-icon">⏱️</div><div><b id="rush-seconds">${game.mode==='free'?'∞':game.seconds+' dtk'}</b><span>Waktu</span></div></div></div>${game.mode==='timed'?`<div class="timer-track"><span id="rush-progress-fill" style="width:${game.seconds/game.duration*100}%"></span></div>`:''}<div class="panel" style="text-align:center"><span class="word-emoji" style="width:62px;height:62px;margin:0 auto 12px;font-size:1.8rem">${item.emoji||'🔤'}</span><div class="level-tag">${profile.settings.mode==='bule'?'WHAT DOES IT MEAN?':'TERJEMAHKAN'}</div><h2 style="font-size:2rem;margin:7px 0">${esc(item.en)}</h2><div class="word-pron">${esc(item.pron||'')}</div><div class="choice-grid" style="margin-top:17px">${game.options.map(option=>`<button class="choice-btn" data-action="rush-answer" data-choice="${esc(option)}">${esc(option)}</button>`).join('')}</div>${game.lastFeedback?`<div class="feedback ${game.lastFeedback.good?'good':'bad'}">${game.lastFeedback.good?'Nice! Jawaban lu benar. Lanjut ke soal berikutnya!':'Belum tepat, bro. Coba perhatikan susunan katanya, ya!'} Soal sebelumnya: <b>${esc(game.lastFeedback.word)}</b> = ${esc(game.lastFeedback.meaning)}</div>`:''}<div class="lesson-tools" style="justify-content:center"><button class="btn btn-ghost btn-small" data-action="speak" data-text="${esc(item.en)}" ${audioAvailable()?'':'disabled'}>🔊 Dengarkan kata</button></div></div></div>`;
}
function renderGrammarBattle(){
  const game=state.grammar;
  if(!game)return `<div class="page-heading"><div><h1>Grammar Battle</h1><p>Tantangan lima soal tentang kalimat dan grammar yang sudah dipelajari.</p></div></div><div class="panel"><p class="panel-subtitle">Soal diambil dari rentang level yang menyesuaikan mode ${esc(modeMeta[profile.settings.mode].name)}. Tiap jawaban menampilkan pola dan penjelasan; salah tidak mengurangi XP.</p><button class="btn btn-primary" style="margin-top:15px" data-action="start-grammar-battle">⚔️ Mulai tantangan</button></div>`;
  if(game.finished)return `<div class="completion-page"><section class="completion-card"><div class="completion-emoji">⚔️</div><h1>Battle selesai!</h1><p>Skor grammar: <b>${game.score}/${game.items.length}</b>. Kesalahanmu bukan penalti—gunakan penjelasan untuk mengingat pola.</p><div class="completion-rewards"><span>⭐ +${game.rewardXp||10} XP</span><span>🪙 +${game.rewardCoins||2} koin</span></div><button class="btn btn-primary" data-action="start-grammar-battle">Tantang lagi</button> <button class="btn btn-secondary" data-action="back">Kembali</button></section></div>`;
  const item=game.items[game.index];
  return `<div class="game-board"><div class="page-heading"><div><span class="level-tag">SOAL ${game.index+1}/${game.items.length}</span><h1 style="margin-top:6px">Pilih bentuk yang benar</h1><p>Skor saat ini: ${game.score}</p></div><button class="btn btn-ghost btn-small" data-action="back">Keluar</button></div><article class="quiz-question"><div class="question-tag">${esc(item.type||'Grammar')}</div><h3>${esc(item.text)}</h3><div class="choice-grid">${item.options.map(option=>`<button class="choice-btn ${game.answer?(option===item.answer?'correct':option===game.answer?'incorrect':''):''}" data-action="grammar-answer" data-choice="${esc(option)}" ${game.answer?'disabled':''}>${esc(option)}</button>`).join('')}</div>${game.answer?`<div class="feedback ${game.answer===item.answer?'good':'bad'}"><b>${game.answer===item.answer?'Nice! Jawaban lu benar. Lanjut ke soal berikutnya!':'Belum tepat, bro. Coba perhatikan susunan katanya, ya! Jawaban benar: '+esc(item.answer)+'.'}</b> ${esc(item.explain)}</div><button class="btn btn-primary" style="margin-top:12px" data-action="grammar-next">${game.index===game.items.length-1?'Selesai':'Soal berikutnya →'}</button>`:''}</article></div>`;
}
function renderPractice(){
  const reviewCount=profile.mistakes.length;const lessonsDone=profile.completed.length;
  return `<div class="page-heading"><div><span class="level-tag">LATIHAN PERSONAL</span><h1>Latihan & pengulangan</h1><p>Ulangi kata yang sering terasa sulit atau ambil kuis dari materi yang sudah terbuka.</p></div></div><div class="two-col"><section class="panel"><div class="mission-top"><div><h2 class="panel-title">Kosakata untuk diulang</h2><p class="panel-subtitle">${reviewCount?`${reviewCount} kata tersimpan dari jawaban yang keliru.`:'Belum ada kata tersimpan. Coba permainan atau kuis untuk menambah latihan.'}</p></div><div class="mission-emoji">🔁</div></div>${reviewCount?renderMistakeChips():`<div class="inline-notice" style="margin-top:13px">Jika kamu salah menjawab kuis, kata terkait otomatis masuk ke daftar review.</div>`}<button class="btn btn-primary" style="margin-top:15px" data-action="start-review" ${reviewCount?'':'disabled'}>Mulai review kosakata</button></section><section class="panel"><div class="mission-top"><div><h2 class="panel-title">Kuis cepat</h2><p class="panel-subtitle">Latih ulang materi yang sudah kamu selesaikan.</p></div><div class="mission-emoji">🧠</div></div><p class="panel-subtitle" style="margin-top:12px">${lessonsDone} pelajaran selesai. Tidak perlu menunggu level berikutnya untuk mengulang materi lama.</p><button class="btn btn-secondary" style="margin-top:15px" data-action="start-random-quiz" ${lessonsDone?'':'disabled'}>Ambil kuis acak</button></section></div><section class="panel" style="margin-top:18px"><h2 class="panel-title">Misi hari ini</h2><p class="panel-subtitle">Selesaikan satu pelajaran untuk memenuhi misi harian. Kamu bisa mengulang Story Mode atau bermain kapan saja tanpa koin.</p><div class="progress-label"><span>Pelajaran selesai hari ini</span><span>${Math.min(profile.daily.lessons||0,1)}/1</span></div><div class="progress-track"><div class="progress-fill" style="width:${profile.daily.lessons?'100':'0'}%"></div></div></section>`;
}
function renderReviewPlay(){
  const review=state.review;if(!review||!review.items.length)return `<div class="empty-state"><div class="emoji">🌱</div><h3>Belum ada kosakata untuk diulang</h3><p>Selesaikan kuis atau permainan; kata yang salah akan otomatis disimpan di sini.</p><button class="btn btn-secondary" data-action="back">Kembali</button></div>`;
  if(review.finished)return `<div class="completion-page"><section class="completion-card"><div class="completion-emoji">🧠</div><h1>Review selesai!</h1><p>Kamu meninjau ${review.items.length} kata. Kata yang masih sulit tetap tersimpan agar dapat diulang lagi nanti.</p><div class="completion-rewards"><span>⭐ +10 XP</span><span>🪙 +2 koin</span></div><button class="btn btn-primary" data-action="nav" data-page="practice">Kembali ke latihan</button></section></div>`;
  const item=review.items[review.index];const shown=review.shown;
  return `<div class="game-board"><div class="page-heading"><div><span class="level-tag">REVIEW ${review.index+1}/${review.items.length}</span><h1 style="margin-top:6px">Ingat arti kata ini?</h1><p>Ucapkan dulu jawabannya sebelum menekan tombol.</p></div><button class="btn btn-ghost btn-small" data-action="back">Keluar</button></div><section class="panel" style="text-align:center"><span class="word-emoji" style="width:66px;height:66px;margin:0 auto 14px;font-size:1.85rem">${item?.emoji||'🔤'}</span><h2 style="font-size:2rem;margin:6px 0">${esc(item?.en||review.raw[review.index]||'word')}</h2><div class="word-pron">${esc(item?.pron||'')}</div><button class="btn btn-ghost btn-small" style="margin-top:10px" data-action="speak" data-text="${esc(item?.en||review.raw[review.index]||'')}">🔊 Dengarkan</button>${shown?`<div class="quiz-result" style="margin-top:17px"><h2 style="font-size:1.3rem">${esc(item?.id||'Artinya belum ada di kamus')}</h2><p>${item?`Contoh: “${esc(lessonById[item.lessonId]?.examples[0]?.en||'')}”`:''}</p></div><div class="hero-actions" style="justify-content:center;margin-top:13px"><button class="btn btn-primary" data-action="review-know">✅ Sudah ingat</button><button class="btn btn-secondary" data-action="review-again">🔁 Ulangi lagi</button></div>`:`<button class="btn btn-primary" style="margin-top:16px" data-action="review-show">Tampilkan arti</button>`}</section></div>`;
}
function renderStats(){
  const history=profile.activityHistory||{};const bars=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=dateKey(d);bars.push({label:['Min','Sen','Sel','Rab','Kam','Jum','Sab'][d.getDay()],value:history[key]||0});}
  const max=Math.max(1,...bars.map(x=>x.value));const levelRows=levels.map(level=>`<div style="margin:13px 0"><div class="progress-label"><span>${level.icon} Level ${level.id} · ${esc(level.name)}</span><span>${progressOf(level)}/${level.lessons.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${progressOf(level)/level.lessons.length*100}%;background:${level.color}"></div></div></div>`).join('');const gameNames={wordHunter:'Word Hunter',grammarPuzzle:'Grammar Puzzle',listeningDetective:'Listening Detective',animeDialogue:'Anime Dialogue',modeBule:'Mode Bule',vocabularyMatch:'Vocabulary Match',speedQuiz:'Speed Quiz',pictureQuiz:'Picture Quiz',grammarBattle:'Grammar Battle',storyMode:'Story Mode',vocabularyReview:'Review kosakata'};const gameRows=Object.entries(profile.gameBest||{}).map(([key,result])=>`<div class="progress-label"><span>${esc(gameNames[key]||key)} · terbaik ${result.bestScore??result.score}/${result.total}</span><span>${result.plays||1} sesi</span></div>`).join('');
  return `<div class="page-heading"><div><h1>Statistik belajar</h1><p>Lihat kebiasaan, progres materi, dan pencapaianmu. Semua tersimpan di perangkat ini.</p></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-card-icon">⭐</div><div><b>${profile.xp}</b><span>Total XP</span></div></div><div class="stat-card"><div class="stat-card-icon">🔥</div><div><b>${displayStreak()} hari</b><span>Streak level berturut-turut</span></div></div><div class="stat-card"><div class="stat-card-icon">📚</div><div><b>${profile.completed.length}</b><span>Pelajaran selesai</span></div></div><div class="stat-card"><div class="stat-card-icon">🪙</div><div><b>${profile.coins}</b><span>Koin virtual</span></div></div></div><div class="two-col" style="margin-top:18px"><section class="panel"><h2 class="panel-title">Aktivitas 7 hari terakhir</h2><p class="panel-subtitle">Jumlah sesi pelajaran atau permainan yang diselesaikan per hari.</p><div class="chart-bars">${bars.map(day=>`<div class="chart-day"><div class="chart-bar" style="height:${Math.max(day.value?14:4,day.value/max*112)}px" title="${day.value} sesi"></div><small>${day.label}</small></div>`).join('')}</div></section><section class="panel"><h2 class="panel-title">Progres per level</h2><p class="panel-subtitle">Materi dibuka bertahap agar kamu menguasai dasarnya.</p>${levelRows}</section></div><section class="panel" style="margin-top:18px"><h2 class="panel-title">Hasil permainan tersimpan</h2>${gameRows||'<p class="panel-subtitle">Belum ada mini-game yang selesai.</p>'}</section><section class="section-title"><div><h2>Lencana</h2><p>Setiap lencana mengikuti pencapaian nyata di aplikasi.</p></div></section><div class="badge-grid">${getBadges().map(renderBadge).join('')}</div><section class="panel" style="margin-top:19px"><h2 class="panel-title">Hasil ujian level</h2>${Object.keys(profile.examResults).length?Object.entries(profile.examResults).map(([id,result])=>`<p class="panel-subtitle" style="margin-top:8px">Level ${id}: ${result.score}/${result.total} benar · ${result.passed?'Lulus':'Belum lulus'}</p>`).join(''):'<p class="panel-subtitle">Belum ada ujian. Ujian tersedia setelah seluruh pelajaran di level selesai.</p>'}</section>`;
}
function renderSettings(){
  const settings=profile.settings;
  const characters=Object.entries(animeCast).map(([id,character])=>`<button class="character-choice ${settings.character===id?'selected':''}" data-action="select-character" data-character="${id}" aria-pressed="${settings.character===id}">${animeAvatar(id,'happy')}<span><b>${esc(character.name)}</b><small>${esc(character.role)} · ${esc(character.description)} · Cara mengajar: ${esc(character.teachingStyle)}</small></span>${settings.character===id?'<span class="mode-check">✓</span>':''}</button>`).join('');
  return `<div class="page-heading"><div><h1>Pengaturan</h1><p>Atur mode, teman belajar, tampilan, dan suara sesuai kenyamananmu. Perubahan disimpan otomatis.</p></div></div><section class="panel mode-panel"><div class="section-title" style="margin:0 0 12px"><div><h2>🎚️ Mode belajar</h2><p>Mode mengubah tingkat materi serta beberapa aturan permainan.</p></div><span class="stat-pill">Aktif: ${modeMeta[settings.mode].name}</span></div>${renderModeSelector()}</section><section class="panel" style="margin-top:15px"><h2 class="panel-title">Pilih teman belajar</h2><p class="panel-subtitle">Setiap karakter muncul dengan arahan yang berkaitan dengan soal, bukan sekadar dekorasi.</p><div class="character-choice-grid">${characters}</div></section>${renderPlayerProfileCard()}<div class="settings-grid" style="margin-top:15px"><section class="panel"><h2 class="panel-title">Tampilan</h2><div class="setting-row"><div><b>Tema gelap</b><small>Kurangi cahaya layar di ruangan redup.</small></div><button class="switch ${settings.theme==='dark'?'on':''}" data-action="toggle-theme" aria-label="Ganti tema"></button></div><div class="setting-row"><div><b>Ukuran teks</b><small>Pilih ukuran yang nyaman dibaca.</small></div><div class="font-controls"><button data-action="font-down" aria-label="Kecilkan teks">A−</button><button data-action="font-reset" aria-label="Ukuran teks normal">A</button><button data-action="font-up" aria-label="Besarkan teks">A+</button></div></div></section><section class="panel"><h2 class="panel-title">Suara & pengucapan</h2><div class="setting-row"><div><b>Musik latar offline</b><small>${settings.musicEnabled?'Melodi lokal menyala; pemutaran dimulai saat tombol ditekan.':'Melodi dibuat di perangkat; tidak ada stream atau unduhan.'}</small></div><button class="switch ${settings.musicEnabled?'on':''}" data-action="toggle-music" aria-label="Aktifkan musik latar offline"></button></div><label class="music-volume-row" for="music-volume"><span><b>Volume musik</b><small><output id="music-volume-value">${Math.round(settings.musicVolume*100)}%</output> · musik terpisah dari suara dialog</small></span><input id="music-volume" type="range" min="0" max="40" step="1" value="${Math.round(settings.musicVolume*100)}" aria-label="Atur volume musik"></label><div class="setting-row"><div><b>Fallback online otomatis</b><small>${settings.onlineSpeechFallback?'Aktif. Jika mode offline gagal, layanan Android dapat memproses ucapan melalui internet. Tekan “Coba offline saja” pada pesan error untuk mematikannya.':'Mati secara default. “Coba online” meminta izin satu kali; audio dapat diproses layanan Android melalui internet.'}</small></div><button class="switch ${settings.onlineSpeechFallback?'on':''}" data-action="toggle-online-speech" aria-label="Izinkan fallback pengenalan suara online otomatis"></button></div><p class="mic-note">Mode offline memakai model Vosk English yang sudah dibundel dalam aplikasi; tidak bergantung pada layanan Android atau paket bahasa terpisah. Pertama kali digunakan, model diekstrak ke penyimpanan privat (sekitar 71 MB) dan membutuhkan kira-kira 300 MB RAM saat pengenalan.</p><p class="mic-note">Suara latihan diambil dari voice English yang sudah tersedia di perangkat. Voice laki-laki/perempuan yang tidak ada akan diganti voice default dan ditandai pada status suara.</p><div class="setting-row"><div><b>Audio pengucapan</b><small>Menggunakan suara bawaan browser/perangkat. Suara English bisa berbeda tiap perangkat.</small></div><button class="switch ${settings.sound?'on':''}" data-action="toggle-sound" aria-label="Aktifkan atau nonaktifkan suara"></button></div><div class="setting-row"><div><b>Efek suara tombol</b><small>Bunyi lembut saat tombol disentuh, serta nada berbeda untuk jawaban benar dan perlu diulang.</small></div><button class="switch ${settings.sfxEnabled?'on':''}" data-action="toggle-sfx" aria-label="Aktifkan efek suara tombol"></button></div><button class="btn btn-secondary btn-small" data-action="test-sfx" ${settings.sfxEnabled?'':'disabled'}>🔊 Tes efek suara tombol</button><div class="setting-row"><div><b>Suara dialog otomatis</b><small>NPC membacakan dialog; voice English disesuaikan dengan gender setiap karakter bila tersedia.</small></div><button class="switch ${settings.autoDialogueVoice?'on':''}" data-action="toggle-dialogue-voice" aria-label="Aktifkan suara dialog otomatis"></button></div><div class="setting-row"><div><b>Mode lambat</b><small>Perlambat pembacaan untuk latihan listening.</small></div><button class="switch ${settings.slowSpeech?'on':''}" data-action="toggle-slow" aria-label="Aktifkan mode lambat"></button></div><div class="setting-row"><div><b>Pilihan suara</b><small>${esc(voiceModeStatus())}. Dialog mengikuti gender karakter bila voice English yang cocok tersedia.</small></div><select class="voice-select" data-setting="voiceGender" aria-label="Pilih jenis suara English"><option value="auto" ${settings.voiceGender==='auto'?'selected':''}>Otomatis</option><option value="female" ${settings.voiceGender==='female'?'selected':''}>Perempuan (jika didukung)</option><option value="male" ${settings.voiceGender==='male'?'selected':''}>Laki-laki (jika didukung)</option></select></div><div class="setting-row"><div><b>Kecepatan TTS</b><small>${Math.round((settings.speechRate||1)*100)}% · atur sesuai kenyamanan.</small></div><div class="audio-rate-control"><button class="btn btn-secondary btn-small" data-action="audio-speed-down" aria-label="Perlambat TTS">−</button><b>${Math.round((settings.speechRate||1)*100)}%</b><button class="btn btn-secondary btn-small" data-action="audio-speed-up" aria-label="Percepat TTS">+</button></div></div><button class="btn btn-secondary btn-small" data-action="speak" data-text="Hello! This is an English Quest audio test." ${audioAvailable()?'':'disabled'}>🔊 Tes suara English</button><p class="mic-note">TTS memakai voice English browser/Android. Jika gagal, UI menampilkan pesan error; audio dapat diulang dan kecepatannya dapat diubah.</p></section></div><section class="panel" style="margin-top:16px"><h2 class="panel-title">Penyimpanan & privasi</h2><p class="panel-subtitle">Progres disimpan otomatis di penyimpanan WebView dan dicadangkan ke penyimpanan privat Android. Jawaban kuis disimpan setiap kali dipilih; tombol Lanjutkan dapat memulihkan kuis yang belum selesai. Latihan offline memakai model Vosk English lokal: audio diproses di perangkat dan tidak dikirim atau disimpan. Fallback online hanya berjalan setelah persetujuan; saat itu layanan Android mungkin memproses audio melalui internet.</p><div class="lesson-tools"><button class="btn btn-primary btn-small" data-action="save-progress-now">💾 Simpan progres sekarang</button><button class="btn btn-secondary btn-small" data-action="export-progress">⬇️ Ekspor progres</button><button class="btn btn-ghost btn-small" data-action="back-to-welcome">Kembali ke layar awal</button><button class="btn btn-ghost btn-small" data-action="reset-progress">Hapus semua progres</button></div><div class="inline-notice" style="margin-top:13px">📶 Aplikasi dirancang offline-first. Pengenal suara English Vosk tersedia di dalam aplikasi dan bekerja tanpa internet. Fallback online mati secara default; percobaan online meminta izin, sedangkan fallback otomatis harus diaktifkan secara eksplisit. Musik dibuat lokal dengan Web Audio.</div></section><section class="panel" style="margin-top:16px"><h2 class="panel-title">Tentang English Quest</h2><p class="panel-subtitle">30 pelajaran terstruktur dalam 6 level, permainan edukatif, Story Mode, kamus, ujian level, dan penyimpanan progres lokal.</p></section>`;
}

