function sukiChallengeMood(game){
  if(game.finished)return game.won?'panicked':'smug';
  if(game.score>=3&&game.index>=2)return 'panicked';
  if(game.score>=2)return 'worried';
  if(game.answer!==null&&game.lastCorrect)return 'shocked';
  return 'smug';
}
function sukiChallengeBanter(game){
  if(game.answer===null){
    if(game.score>=3)return 'N-no, you are already this close? Stop getting everything right!';
    if(game.score>=2)return 'Two points already? Hmph. I am still completely calm. Obviously.';
    return game.rank?`I have trained through ${game.rank} wins. You will not catch me that easily!`:'Hah! This challenge is easy for me. Try to keep up!';
  }
  if(game.lastCorrect){
    if(game.score>=3)return 'WHAT?! You are one point from winning! That answer was… probably a fluke!';
    if(game.score>=2)return 'Wait, you got another one? I meant to let you feel confident. Maybe.';
    return 'Hmph, correct. Beginner’s luck. I am still the rival to beat!';
  }
  if(game.score>=2)return 'Hah, a miss! That is one point back for me—but why are you still catching up?!';
  return 'Too easy! I knew you would miss that one. Come on, make this interesting!';
}
