  if(audioState.status==='paused')return `<div class="audio-indicator paused" role="status"><span>⏸ ${english?'Audio paused':'Audio dijeda'}</span><button data-action="audio-resume" aria-label="${english?'Resume audio':'Lanjutkan audio'}">▶</button><button data-action="audio-stop" aria-label="${english?'Stop audio':'Hentikan audio'}">×</button></div>`;
  return `<div class="audio-indicator error" role="status"><span>⚠️ ${english?'Audio failed':'Audio gagal'}</span><button data-action="audio-stop" aria-label="${english?'Close audio status':'Tutup status audio'}">×</button></div>`;
