  if(!audioAvailable()){showToast(profile.settings.mode==='bule'?'Text-to-speech is unavailable on this device. Use the written guidance and try again later.':'TTS tidak tersedia di perangkat ini. Gunakan petunjuk baca tertulis.');return;}
  stopAudio();const token=++audioToken;nativeAudioToken=token;const gender=requestedGender||profile.settings.voiceGender||'auto';const baseRate=Number(profile.settings.speechRate)||1;const rate=Math.max(.6,Math.min(1.2,baseRate*(slow?.72:(profile.settings.slowSpeech?.82:1))));
