function completeSpeechRecognition(requestId,transcript){
  if(String(requestId)!==String(speechRequestToken)||!state.speakingPractice)return;
  const practice=state.speakingPractice;practice.transcript=String(transcript||'').trim();practice.guide=pronunciationGuide(practice.target,practice.guide||'');
  const score=pronunciationMatch(practice.target,practice.transcript).score;practice.lastScore=score;
  if(score>=75){practice.status='result';render();playUiSound('success');if(profile.settings.sound&&audioAvailable())speak('Great job! That was clear.',false);return;}
  practice.attempts=(Number(practice.attempts)||0)+1;
  if(practice.attempts===1){practice.status='retry';render();playUiSound('miss');if(profile.settings.sound&&audioAvailable())speak('Not quite. Please try again!',false);return;}
  practice.status='guided';render();playUiSound('miss');if(profile.settings.sound&&audioAvailable())speak(practice.target,true);
}
